export function arqSimulation(input={}){
 const p={protocol:'gbn',base:0,loss:1,tx:1,rtt:9,...input};if(!['stopwait','gbn','sr'].includes(p.protocol)||!Number.isInteger(p.loss)||p.loss< -1||p.loss>3||!Number.isInteger(p.base)||p.base<0||p.base>10000||!Number.isFinite(p.tx)||p.tx<=0||p.tx>10000||!Number.isFinite(p.rtt)||p.rtt<0||p.rtt>10000)throw Error('ARQ: giao thức, gói mất -1–3, Seq đầu 0–10000 và thời gian hợp lệ.');
 const steps=[],events=[],buffer=new Set(),delivered=[],acks=new Set(),retransmit=[];let expected=0,sendBase=0,size=p.protocol==='stopwait'?1:4;const num=i=>p.base+i,win=()=>sendBase>=4?'Đã xác nhận hết':Array.from({length:Math.min(size,4-sendBase)},(_,j)=>num(sendBase+j)).join(', ');
 function snapshot(text,event){if(event)events.push(event);steps.push({text,scene:{kind:'sequence',actors:['Sender','Receiver'],events:structuredClone(events),active:events.length-1},table:{heads:['Trạng thái lúc này','Giá trị'],rows:[['Cửa sổ gửi',win()],['Byte/gói?','Seq theo gói (không phải byte TCP)'],['Receiver đang chờ',num(expected)],['Đã giao ứng dụng',delivered.map(num).join(', ')||'Chưa có'],['Buffer ngoài thứ tự',[...buffer].sort().map(num).join(', ')||'Trống'],['ACK đã tới sender',[...acks].sort().map(num).join(', ')||'Chưa có']]}})}
 function receive(i,retry=false){if(p.protocol==='sr'){if(i>=expected)buffer.add(i);while(buffer.has(expected)){buffer.delete(expected);delivered.push(expected);expected++}}else if(i===expected){delivered.push(i);expected++}
  let ack=p.protocol==='gbn'?expected-1:i;let outOfOrder=p.protocol==='gbn'&&i>=expected;snapshot(outOfOrder?`GBN bỏ gói ${num(i)} ngoài thứ tự, vẫn chờ ${num(expected)}.`:p.protocol==='sr'&&buffer.size?`SR giữ ${num(i)} trong buffer, ACK riêng nhưng chưa giao qua lỗ hổng ${num(expected)}.`:`Nhận gói ${num(i)}${retry?' phát lại':''}, giao chuỗi liên tục tới ứng dụng.`);
  if(p.protocol==='gbn')for(let j=0;j<=ack;j++)acks.add(j);else acks.add(i);while(acks.has(sendBase))sendBase++;
  snapshot(`${p.protocol==='gbn'?'ACK cộng dồn':'ACK riêng'} ${num(ack)} tới sender; cửa sổ chỉ trượt qua ACK liên tục.`,{from:1,to:0,label:'ACK '+num(ack)})
 }
 snapshot(`Bắt đầu ${p.protocol}; cửa sổ ${size} gói, số thứ tự đầu ${p.base}.`);
 for(let i=0;i<4;i++){let lost=i===p.loss;snapshot(`Gửi gói ${num(i)}${lost?'; gói bị mất, receiver không có gì để ACK.':'.'}`,{from:0,to:1,label:'Gói '+num(i)+(lost?' · mất':''),lost});if(lost){if(p.protocol==='stopwait'){retransmit.push(i);snapshot(`Timer hết hạn: stop-and-wait chỉ phát lại gói ${num(i)}.`,{from:0,to:1,label:'Timeout: gửi lại '+num(i)});receive(i,true)}}else receive(i)}
 let before=[...delivered,...buffer].sort((a,b)=>a-b);if(p.loss>=0&&p.protocol!=='stopwait'){let retry=p.protocol==='sr'?[p.loss]:Array.from({length:4-sendBase},(_,j)=>sendBase+j);for(let i of retry){retransmit.push(i);snapshot(p.protocol==='sr'?`Timer riêng gói ${num(i)} hết hạn: chỉ phát lại gói này.`:`Timer gói cũ nhất chưa ACK hết hạn: GBN phát lại ${retry.map(num).join(', ')}.`,{from:0,to:1,label:'Truyền lại '+num(i)});receive(i,true)}}
 let u=p.tx/(p.rtt+p.tx)*100;snapshot(`Kết thúc: đã giao ${delivered.map(num).join(', ')} đúng thứ tự.${p.protocol==='stopwait'?' U không mất gói = (L/R)/(RTT+L/R) = '+Number(u.toFixed(6))+'%.':' Cửa sổ gửi đã qua toàn bộ ACK liên tục.'}`);
 return {type:'arq',title:'Stop-and-wait · Go-Back-N · Selective Repeat',params:p,steps,fields:[{name:'protocol',label:'Giao thức',type:'select',values:['stopwait','gbn','sr'],value:p.protocol},{name:'loss',label:'Vị trí gói mất (-1: không mất; 0–3 trong lượt)',type:'number',min:-1,max:3,step:1,value:p.loss},{name:'tx',label:'L/R (ms)',type:'number',min:.000001,max:10000,step:.001,value:p.tx},{name:'rtt',label:'RTT (ms)',type:'number',min:0,max:10000,step:.1,value:p.rtt}],metrics:{received:before.map(num),retransmit:retransmit.map(num),u,delivered:delivered.map(num)},notes:'Mô hình 4 gói, không vòng số thứ tự. Seq/ACK theo gói, khác TCP theo byte. SR cần cửa sổ ≤ nửa không gian số; ví dụ dùng không gian số đủ lớn. U là cơ sở không mất gói, bỏ phát ACK; truyền lại làm hiệu suất thực giảm. Hoạt ảnh sự kiện không theo tỷ lệ thời gian.'};
}
